window.READING_REVIEW_DATA = {"items":[{"id":"drama-v-1","term":"probationary","type":"word","sourceOrder":1,"zh":"试用期的","pos":"adj.","ipa":"prəˈbeɪʃənəri","stars":5,"note":"probation 试用／缓刑；不是“概率的”","paragraph":"听力原文","memory":{"parts":"probation（试用／考察）＋ -ary","tip":"由 probation 记 probationary year，即试用年度；不要与 probability（概率）混淆。","family":"probation, probationary"},"examples":[{"en":"Now, part of my job is to support you during your probationary year.","zh":"我的部分职责是在你的试用年度支持你。","source":"original","number":7}]},{"id":"drama-v-2","term":"qualification","type":"word","sourceOrder":2,"zh":"资质、资格","pos":"n.","ipa":"ˌkwɒlɪfɪˈkeɪʃən","stars":4,"note":"学历、合格证书；资格要求；diploma 为具体证书，可对应 qualification","paragraph":"词汇与语块","memory":{"parts":"qualify（取得资格）→ qualification","tip":"将动词 qualify 与名词 qualification 配对记；本文具体的 diploma 对应抽象的资格。","family":"qualify, qualified, qualification"},"examples":[{"en":"Completing the diploma will give Ed a professional qualification.","zh":"完成这项文凭课程后，埃德将获得一项专业资格。","source":"supplemental"}]},{"id":"drama-v-3","term":"workshop","type":"word","sourceOrder":3,"zh":"工作坊、实践课","pos":"n.","ipa":"ˈwɜːkʃɒp","stars":2,"note":"研讨班；工作车间；不是泛指任何讲座","paragraph":"听力原文","examples":[{"en":"You will hear a discussion between Fiona, who is the head of a college drama department, and a new tutor called Ed, who is preparing to run a voice coaching workshop for drama students.","zh":"你将听到菲奥娜（学院戏剧系主任）与新导师埃德的讨论；埃德正在准备为戏剧专业学生开设声音指导工作坊。","source":"original","number":2},{"en":"So let's ensure that you're clear about what you'll be doing in the first voice coaching workshop you run next week.","zh":"因此，我们要确认你清楚下周首场声音指导工作坊要做些什么。","source":"original","number":8},{"en":"Anyway, I've thought through the workshop, and I've done a plan to highlight the key areas I intend to cover.","zh":"总之，我已经把工作坊仔细想过，并拟定了一份计划，突出要讲的重点领域。","source":"original","number":14}]},{"id":"drama-v-4","term":"project","type":"word","sourceOrder":4,"zh":"（使声音）传到远处","pos":"v.","ipa":"prəˈdʒekt","stars":3,"note":"投射；预计；此处不是名词 project /ˈprɒdʒekt/“项目”","paragraph":"听力原文","examples":[{"en":"I'll be observing you working with the students as you show them how to project their voices on stage.","zh":"我会在你教学生如何在舞台上将声音清晰传出去时，观察你的教学表现。","source":"original","number":10}]},{"id":"drama-v-5","term":"projection","type":"word","sourceOrder":5,"zh":"声音传送、投射","pos":"n.","ipa":"prəˈdʒekʃən","stars":4,"note":"预测；放映；voice projection 不等于 shout","paragraph":"听力原文","memory":{"parts":"project（投射）→ projection","tip":"project 的名词形式；voice projection 强调声音传远，不能直接等同于 shouting。","family":"project, projection"},"examples":[{"en":"So bearing in mind that voice projection is not shouting, later in the course, you'll need to work in a much bigger space.","zh":"因此要记住，声音投射不是喊叫；在课程后期，你需要到大得多的空间训练。","source":"original","number":43}]},{"id":"drama-v-6","term":"observe","type":"word","sourceOrder":6,"zh":"观察（教学过程）","pos":"v.","ipa":"əbˈzɜːv","stars":3,"note":"遵守（规则）；庆祝（节日）；observe rules = 遵守规则","paragraph":"听力原文","examples":[{"en":"I'll be observing you working with the students as you show them how to project their voices on stage.","zh":"我会在你教学生如何在舞台上将声音清晰传出去时，观察你的教学表现。","source":"original","number":10}]},{"id":"drama-v-7","term":"evaluate","type":"word","sourceOrder":7,"zh":"评估表现","pos":"v.","ipa":"ɪˈvæljueɪt","stars":4,"note":"评价、估价；常见于研究与教育语境","paragraph":"听力原文","memory":{"parts":"evaluate → evaluation（词族）","tip":"用 evaluate performance 和 performance evaluation 成对记“评估表现”。","family":"evaluate, evaluation, evaluator"},"examples":[{"en":"I'll be evaluating how you cope with the practical activities as well as the theory.","zh":"我会评估你应对实践活动和理论教学的能力。","source":"original","number":11}]},{"id":"drama-v-8","term":"cope","type":"word","sourceOrder":8,"zh":"应付、处理","pos":"v.","ipa":"kəʊp","stars":3,"note":"cope with pressure/stress；搭配介词 with","paragraph":"听力原文","examples":[{"en":"I'll be evaluating how you cope with the practical activities as well as the theory.","zh":"我会评估你应对实践活动和理论教学的能力。","source":"original","number":11}]},{"id":"drama-v-9","term":"practical","type":"word","sourceOrder":9,"zh":"实践性的","pos":"adj.","ipa":"ˈpræktɪkəl","stars":3,"note":"实际的、可行的；practical activities 非“练习册”","paragraph":"听力原文","examples":[{"en":"I'll be evaluating how you cope with the practical activities as well as the theory.","zh":"我会评估你应对实践活动和理论教学的能力。","source":"original","number":11}]},{"id":"drama-v-10","term":"theory","type":"word","sourceOrder":10,"zh":"理论","pos":"n.","ipa":"ˈθɪəri","stars":2,"note":"学说、理论基础；与 practice 对照","paragraph":"听力原文","examples":[{"en":"I'll be evaluating how you cope with the practical activities as well as the theory.","zh":"我会评估你应对实践活动和理论教学的能力。","source":"original","number":11}]},{"id":"drama-v-11","term":"diploma","type":"word","sourceOrder":11,"zh":"文凭、结业证书","pos":"n.","ipa":"dɪˈpləʊmə","stars":4,"note":"职业资格证书；不必等同于 university degree","paragraph":"听力原文","memory":{"parts":"diploma（整体场景记忆）","tip":"把完成培训后领取文凭的画面与 diploma 绑定；不是所有 diploma 都等于大学学位，不硬拆词根。","family":"diploma, qualification, certificate"},"examples":[{"en":"And if all goes well, you'll then have finished the final stage of your voice coach diploma.","zh":"如果一切顺利，你就完成声音指导师文凭的最后阶段了。","source":"original","number":12}]},{"id":"drama-v-12","term":"highlight","type":"word","sourceOrder":12,"zh":"突出计划重点","pos":"v.","ipa":"ˈhaɪlaɪt","stars":3,"note":"强调；使显眼；也可作 n. 最精彩的部分","paragraph":"听力原文","examples":[{"en":"Anyway, I've thought through the workshop, and I've done a plan to highlight the key areas I intend to cover.","zh":"总之，我已经把工作坊仔细想过，并拟定了一份计划，突出要讲的重点领域。","source":"original","number":14}]},{"id":"drama-v-13","term":"cover","type":"word","sourceOrder":13,"zh":"涵盖、讲授（主题）","pos":"v.","ipa":"ˈkʌvə","stars":2,"note":"报道；支付；覆盖；熟词生义：cover material = 讲授内容","paragraph":"听力原文","examples":[{"en":"Anyway, I've thought through the workshop, and I've done a plan to highlight the key areas I intend to cover.","zh":"总之，我已经把工作坊仔细想过，并拟定了一份计划，突出要讲的重点领域。","source":"original","number":14}]},{"id":"drama-v-14","term":"pattern","type":"word","sourceOrder":14,"zh":"座位布局、排列方式","pos":"n.","ipa":"ˈpætən","stars":2,"note":"模式；规律；花纹；此处非衣服图案","paragraph":"听力原文","examples":[{"en":"I'm glad you've thought about seating patterns.","zh":"我很高兴你考虑了座位排列方式。","source":"original","number":18},{"en":"You say you want to begin with the students sitting in star-shaped patterns.","zh":"你说打算先让学生按照星形布局坐好。","source":"original","number":19},{"en":"There are various seating patterns you can use at this stage.","zh":"在这个阶段，你可以选择多种座位布局。","source":"original","number":21}]},{"id":"drama-v-15","term":"trainee","type":"word","sourceOrder":15,"zh":"受训学员","pos":"n.","ipa":"ˌtreɪˈniː","stars":4,"note":"实习生、培训人员；与 trainer 讲师区分","paragraph":"听力原文","memory":{"parts":"train（培训）＋ -ee（接受者）","tip":"受培训的人是 trainee，提供培训的人是 trainer，注意词尾区别。","family":"train, trainee, trainer"},"examples":[{"en":"I like trainees sitting cross-legged in a circle.","zh":"我喜欢让学员们盘腿围坐成圈。","source":"original","number":22}]},{"id":"drama-v-16","term":"cross-legged","type":"word","sourceOrder":16,"zh":"盘腿（坐）","pos":"adj./adv.","ipa":"ˌkrɒs ˈleɡɪd","stars":3,"note":"身体姿势表达；legged 尾音 /ɪd/","paragraph":"听力原文","examples":[{"en":"I like trainees sitting cross-legged in a circle.","zh":"我喜欢让学员们盘腿围坐成圈。","source":"original","number":22}]},{"id":"drama-v-17","term":"circle","type":"word","sourceOrder":17,"zh":"圆圈","pos":"n.","ipa":"ˈsɜːkəl","stars":1,"note":"圈子；循环；in a circle = 围成圈","paragraph":"听力原文","examples":[{"en":"I like trainees sitting cross-legged in a circle.","zh":"我喜欢让学员们盘腿围坐成圈。","source":"original","number":22}]},{"id":"drama-v-18","term":"represent","type":"word","sourceOrder":18,"zh":"用图示表示","pos":"v.","ipa":"ˌreprɪˈzent","stars":3,"note":"代表；体现；represent diagrammatically","paragraph":"听力原文","examples":[{"en":"But actually, all these can be represented diagrammatically, which would be clearer than going into lots of detailed explanations like you've done here.","zh":"但实际上，这些布局都能用示意图呈现，这比你这里写大量细节解释更清晰。","source":"original","number":24}]},{"id":"drama-v-19","term":"diagrammatically","type":"word","sourceOrder":19,"zh":"以图示方式","pos":"adv.","ipa":"ˌdaɪəɡrəˈmætɪkli","stars":5,"note":"用示意图表示；关注词根 diagram","paragraph":"听力原文","memory":{"parts":"diagram（示意图）→ diagrammatic → diagrammatically","tip":"名词变形容词，再加 -ly 成副词；指以图示方式呈现计划，不代表座位形式必须如此。","family":"diagram, diagrammatic, diagrammatically"},"examples":[{"en":"But actually, all these can be represented diagrammatically, which would be clearer than going into lots of detailed explanations like you've done here.","zh":"但实际上，这些布局都能用示意图呈现，这比你这里写大量细节解释更清晰。","source":"original","number":24}]},{"id":"drama-v-20","term":"objective","type":"word","sourceOrder":20,"zh":"课程目标","pos":"n.","ipa":"əbˈdʒektɪv","stars":3,"note":"目的、客观的（adj.）；词性变化：objective adj. 客观的","paragraph":"听力原文","examples":[{"en":"So in the initial phase, I explain the objectives of the session.","zh":"因此在初始阶段，我会说明本次课程的目标。","source":"original","number":29}]},{"id":"drama-v-21","term":"initial","type":"word","sourceOrder":21,"zh":"最初的","pos":"adj.","ipa":"ɪˈnɪʃəl","stars":3,"note":"首字母（n.）；initial phase = 初始阶段","paragraph":"听力原文","examples":[{"en":"So in the initial phase, I explain the objectives of the session.","zh":"因此在初始阶段，我会说明本次课程的目标。","source":"original","number":29}]},{"id":"drama-v-22","term":"phase","type":"word","sourceOrder":22,"zh":"阶段","pos":"n.","ipa":"feɪz","stars":3,"note":"时期；相位；phase/stage 同义替换","paragraph":"听力原文","examples":[{"en":"So in the initial phase, I explain the objectives of the session.","zh":"因此在初始阶段，我会说明本次课程的目标。","source":"original","number":29}]},{"id":"drama-v-23","term":"briskly","type":"word","sourceOrder":23,"zh":"轻快而迅速地","pos":"adv.","ipa":"ˈbrɪskli","stars":3,"note":"迅速、活跃地；walk briskly","paragraph":"听力原文","examples":[{"en":"Then in the first activity, you say they should quickly rise, walk briskly around the room, weaving in and out to avoid each other.","zh":"随后，在第一项活动中，你计划让学生迅速起身，在房间里快步穿行，避开彼此。","source":"original","number":31}]},{"id":"drama-v-24","term":"weave","type":"word","sourceOrder":24,"zh":"穿行、迂回移动","pos":"v.","ipa":"wiːv","stars":3,"note":"编织；熟词生义 weave in and out = 穿梭","paragraph":"听力原文","examples":[{"en":"Then in the first activity, you say they should quickly rise, walk briskly around the room, weaving in and out to avoid each other.","zh":"随后，在第一项活动中，你计划让学生迅速起身，在房间里快步穿行，避开彼此。","source":"original","number":31}]},{"id":"drama-v-25","term":"confined","type":"word","sourceOrder":25,"zh":"有限的、狭窄的","pos":"adj.","ipa":"kənˈfaɪnd","stars":4,"note":"受限制的；被禁闭的；confined space","paragraph":"听力原文","memory":{"parts":"confine（限制）＋ -ed","tip":"confined space 是活动范围受限的空间；和 consent、confident 区分。","family":"confine, confined, confinement"},"examples":[{"en":"I think it's important that they don't get in each other's way and that they learn to move within a confined space, aware of other people, but primarily concentrating on their own thoughts.","zh":"我认为重要的是：不要互相挡路；要学会在有限的空间中移动，留意他人，但主要关注自己的想法。","source":"original","number":33}]},{"id":"drama-v-26","term":"aware","type":"word","sourceOrder":26,"zh":"意识到的","pos":"adj.","ipa":"əˈweə","stars":2,"note":"有意识的、了解的；be aware of","paragraph":"听力原文","examples":[{"en":"I think it's important that they don't get in each other's way and that they learn to move within a confined space, aware of other people, but primarily concentrating on their own thoughts.","zh":"我认为重要的是：不要互相挡路；要学会在有限的空间中移动，留意他人，但主要关注自己的想法。","source":"original","number":33}]},{"id":"drama-v-27","term":"primarily","type":"word","sourceOrder":27,"zh":"主要地","pos":"adv.","ipa":"praɪˈmerəli","stars":4,"note":"首先、本质上；Q23 关键转向词","paragraph":"听力原文","memory":{"parts":"primary（主要的）→ primarily（主要地）","tip":"形容词变副词时 y 变 i；but primarily 后的信息优先级最高。","family":"primary, primarily"},"examples":[{"en":"I think it's important that they don't get in each other's way and that they learn to move within a confined space, aware of other people, but primarily concentrating on their own thoughts.","zh":"我认为重要的是：不要互相挡路；要学会在有限的空间中移动，留意他人，但主要关注自己的想法。","source":"original","number":33}]},{"id":"drama-v-28","term":"concentrate","type":"word","sourceOrder":28,"zh":"集中注意","pos":"v.","ipa":"ˈkɒnsəntreɪt","stars":4,"note":"浓缩（液体）；熟词生义：concentrate solution = 浓缩溶液","paragraph":"听力原文","memory":{"parts":"concentrate → concentration（词族）","tip":"用 concentration 与 concentrate on one's thoughts 联结注意力集中；另有浓缩义。","family":"concentrate, concentration"},"examples":[{"en":"I think it's important that they don't get in each other's way and that they learn to move within a confined space, aware of other people, but primarily concentrating on their own thoughts.","zh":"我认为重要的是：不要互相挡路；要学会在有限的空间中移动，留意他人，但主要关注自己的想法。","source":"original","number":33}]},{"id":"drama-v-29","term":"omit","type":"word","sourceOrder":29,"zh":"遗漏、未提到","pos":"v.","ipa":"əˈmɪt","stars":4,"note":"省略、删去；omit to mention","paragraph":"听力原文","memory":{"parts":"omit → omission（词族）","tip":"把 omit to mention 与 omission 成对记，过去式 omitted 双写 t，名词用 ss。","family":"omit, omitted, omission"},"examples":[{"en":"But in your plan, you've omitted to mention that in the second activity, you will get the students to pair off.","zh":"但你的计划漏写了：第二项活动要让学生两两配对。","source":"original","number":35}]},{"id":"drama-v-30","term":"pair","type":"word","sourceOrder":30,"zh":"两两配对","pos":"v./n.","ipa":"peə","stars":1,"note":"一对、配成对；pair off ≠ 指定搭档","paragraph":"听力原文","examples":[{"en":"But in your plan, you've omitted to mention that in the second activity, you will get the students to pair off.","zh":"但你的计划漏写了：第二项活动要让学生两两配对。","source":"original","number":35}]},{"id":"drama-v-31","term":"essential","type":"word","sourceOrder":31,"zh":"至关重要的","pos":"adj.","ipa":"ɪˈsenʃəl","stars":3,"note":"必要的；要素（n.）；it is essential for sb to do","paragraph":"听力原文","examples":[{"en":"So you need to rethink that section and include reasons why it's essential for them to listen to each other talking.","zh":"因此，你需要重新考虑该部分，并解释为什么互相倾听说话非常必要。","source":"original","number":36}]},{"id":"drama-v-32","term":"posture","type":"word","sourceOrder":32,"zh":"体态、姿势","pos":"n.","ipa":"ˈpɒstʃə","stars":4,"note":"立场、姿态；affect breathing and voice","paragraph":"听力原文","memory":{"parts":"posture（身体姿势 → 立场；语义联想）","tip":"本文先想象站姿影响呼吸，再扩展到表达态度的 posture；不按外形硬拆词根。","family":"posture, postural"},"examples":[{"en":"And at the same time, get them to think about their posture because that governs their lung capacity and most crucially, their breathing.","zh":"同时让他们注意姿势，因为姿势会影响肺活量，更关键的是呼吸。","source":"original","number":38}]},{"id":"drama-v-33","term":"govern","type":"word","sourceOrder":33,"zh":"影响、决定（肺活量）","pos":"v.","ipa":"ˈɡʌvən","stars":3,"note":"统治、管理；熟词生义：因素决定结果","paragraph":"听力原文","examples":[{"en":"And at the same time, get them to think about their posture because that governs their lung capacity and most crucially, their breathing.","zh":"同时让他们注意姿势，因为姿势会影响肺活量，更关键的是呼吸。","source":"original","number":38}]},{"id":"drama-v-34","term":"lung","type":"word","sourceOrder":34,"zh":"肺","pos":"n.","ipa":"lʌŋ","stars":1,"note":"肺部健康；lung capacity 固定搭配","paragraph":"听力原文","examples":[{"en":"And at the same time, get them to think about their posture because that governs their lung capacity and most crucially, their breathing.","zh":"同时让他们注意姿势，因为姿势会影响肺活量，更关键的是呼吸。","source":"original","number":38}]},{"id":"drama-v-35","term":"capacity","type":"word","sourceOrder":35,"zh":"肺活量","pos":"n.","ipa":"kəˈpæsəti","stars":4,"note":"容量；生产能力；能力；熟词生义：capacity 不是只有“空间容量”","paragraph":"听力原文","memory":{"parts":"capacity → capable（词族联想）","tip":"用 lung capacity 记肺活量，用 capable 记有能力；capacity 既可指容量，也可指能力。","family":"capacity, capable, capability"},"examples":[{"en":"And at the same time, get them to think about their posture because that governs their lung capacity and most crucially, their breathing.","zh":"同时让他们注意姿势，因为姿势会影响肺活量，更关键的是呼吸。","source":"original","number":38}]},{"id":"drama-v-36","term":"crucially","type":"word","sourceOrder":36,"zh":"最关键的是","pos":"adv.","ipa":"ˈkruːʃəli","stars":4,"note":"极为重要地；强调答案 breathing","paragraph":"听力原文","memory":{"parts":"crucial（关键的）＋ -ly","tip":"副词强调最关键的信息；most crucially 后的 breathing 比前面背景更接近答案。","family":"crucial, crucially"},"examples":[{"en":"And at the same time, get them to think about their posture because that governs their lung capacity and most crucially, their breathing.","zh":"同时让他们注意姿势，因为姿势会影响肺活量，更关键的是呼吸。","source":"original","number":38}]},{"id":"drama-v-37","term":"breathing","type":"word","sourceOrder":37,"zh":"呼吸","pos":"n.","ipa":"ˈbriːðɪŋ","stars":3,"note":"呼吸技巧；区别 breath n. /breθ/ 与 breathe v. /briːð/","paragraph":"听力原文","examples":[{"en":"And at the same time, get them to think about their posture because that governs their lung capacity and most crucially, their breathing.","zh":"同时让他们注意姿势，因为姿势会影响肺活量，更关键的是呼吸。","source":"original","number":38}]},{"id":"drama-v-38","term":"rehearse","type":"word","sourceOrder":38,"zh":"排练","pos":"v.","ipa":"rɪˈhɜːs","stars":4,"note":"预演、练习；戏剧与演讲常考","paragraph":"听力原文","memory":{"parts":"rehearse → rehearsal（词族）","tip":"动词排练与名词 rehearsal 成对记；不要仅凭 re- 就把整个词硬拆为“再次听”。","family":"rehearse, rehearsal"},"examples":[{"en":"Of course, a common issue in the UK is that we rehearse in small rooms, then transfer to a larger stage.","zh":"当然，英国常见的一个问题是：先在小房间排练，再转到更大的舞台。","source":"original","number":42}]},{"id":"drama-v-39","term":"transfer","type":"word","sourceOrder":39,"zh":"转移至大舞台","pos":"v.","ipa":"trænsˈfɜː","stars":3,"note":"调动；转账；转学；transfer to + 地点","paragraph":"听力原文","examples":[{"en":"Of course, a common issue in the UK is that we rehearse in small rooms, then transfer to a larger stage.","zh":"当然，英国常见的一个问题是：先在小房间排练，再转到更大的舞台。","source":"original","number":42}]},{"id":"drama-v-40","term":"shout","type":"word","sourceOrder":40,"zh":"喊叫","pos":"v.","ipa":"ʃaʊt","stars":1,"note":"大声说；voice projection ≠ shouting","paragraph":"听力原文","examples":[{"en":"So bearing in mind that voice projection is not shouting, later in the course, you'll need to work in a much bigger space.","zh":"因此要记住，声音投射不是喊叫；在课程后期，你需要到大得多的空间训练。","source":"original","number":43}]},{"id":"drama-v-41","term":"enclosed","type":"word","sourceOrder":41,"zh":"封闭的、室内的","pos":"adj.","ipa":"ɪnˈkləʊzd","stars":4,"note":"被围住的；Q25 允许 outdoor, 偏好 enclosed","paragraph":"听力原文","memory":{"parts":"enclose（围住）＋ -ed","tip":"“被围住的”联想到封闭空间；本文首选 enclosed，并非必须排除一切户外场地。","family":"enclose, enclosed, enclosure"},"examples":[{"en":"Does it have to be an enclosed space?","zh":"一定要是封闭的室内空间吗？","source":"original","number":44},{"en":"Ideally, an enclosed space, but there's no reason why you couldn't go somewhere outdoors, although I'd avoid a very public space like a park.","zh":"理想情况是封闭空间，但也完全可以去户外；只是我会避免公园那样过于公共的场所。","source":"original","number":46}]},{"id":"drama-v-42","term":"ultimately","type":"word","sourceOrder":42,"zh":"最终","pos":"adv.","ipa":"ˈʌltɪmətli","stars":4,"note":"归根结底；往往连接终极目标","paragraph":"听力原文","memory":{"parts":"ultimate（最终的）＋ -ly","tip":"从 ultimate goal 记 ultimately“最终”，用于说明最后会在剧院工作。","family":"ultimate, ultimately"},"examples":[{"en":"I suppose it does because ultimately they're going to work in a theater.","zh":"我想应该是，因为最终他们会在剧院工作。","source":"original","number":45}]},{"id":"drama-v-43","term":"ideally","type":"word","sourceOrder":43,"zh":"理想情况下","pos":"adv.","ipa":"aɪˈdɪəli","stars":3,"note":"最好是；“首选”不等于“必须”","paragraph":"听力原文","examples":[{"en":"Ideally, an enclosed space, but there's no reason why you couldn't go somewhere outdoors, although I'd avoid a very public space like a park.","zh":"理想情况是封闭空间，但也完全可以去户外；只是我会避免公园那样过于公共的场所。","source":"original","number":46}]},{"id":"drama-v-44","term":"outdoors","type":"word","sourceOrder":44,"zh":"在户外","pos":"adv.","ipa":"ˌaʊtˈdɔːz","stars":3,"note":"室外；与 indoors 对比","paragraph":"听力原文","examples":[{"en":"Ideally, an enclosed space, but there's no reason why you couldn't go somewhere outdoors, although I'd avoid a very public space like a park.","zh":"理想情况是封闭空间，但也完全可以去户外；只是我会避免公园那样过于公共的场所。","source":"original","number":46}]},{"id":"drama-v-45","term":"convey","type":"word","sourceOrder":45,"zh":"传达情绪","pos":"v.","ipa":"kənˈveɪ","stars":4,"note":"运输；表达；convey emotion/message","paragraph":"听力原文","memory":{"parts":"convey → conveyance（词族）","tip":"用“传递”串联运输物品与传达情绪；convey emotion 是本文义。","family":"convey, conveyance"},"examples":[{"en":"Now, your next activity on how to convey emotion on stage is fine, but your selection of texts for the students to experience emotional depth leaves a little to be desired.","zh":"接下来你关于舞台情感表达的活动本身不错，但供学生体验情感深度的选文仍有改进空间。","source":"original","number":49}]},{"id":"drama-v-46","term":"emotion","type":"word","sourceOrder":46,"zh":"情绪、情感","pos":"n.","ipa":"ɪˈməʊʃən","stars":2,"note":"情绪反应；multiple emotions","paragraph":"听力原文","examples":[{"en":"Now, your next activity on how to convey emotion on stage is fine, but your selection of texts for the students to experience emotional depth leaves a little to be desired.","zh":"接下来你关于舞台情感表达的活动本身不错，但供学生体验情感深度的选文仍有改进空间。","source":"original","number":49},{"en":"You need to consider the different kind of emotion that each extract should present, from sorrow through to ecstasy.","zh":"你需要考虑每篇节选应该呈现的各种情绪，从悲伤直到狂喜。","source":"original","number":51}]},{"id":"drama-v-47","term":"selection","type":"word","sourceOrder":47,"zh":"选文、选择结果","pos":"n.","ipa":"sɪˈlekʃən","stars":3,"note":"挑选过程；一组选定物；selection of texts","paragraph":"听力原文","examples":[{"en":"Now, your next activity on how to convey emotion on stage is fine, but your selection of texts for the students to experience emotional depth leaves a little to be desired.","zh":"接下来你关于舞台情感表达的活动本身不错，但供学生体验情感深度的选文仍有改进空间。","source":"original","number":49}]},{"id":"drama-v-48","term":"extract","type":"word","sourceOrder":48,"zh":"节选、摘录","pos":"n.","ipa":"ˈekstrækt","stars":3,"note":"提取物；v. 提取 /ɪkˈstrækt/；名动重音变化","paragraph":"听力原文","examples":[{"en":"It's not enough to include a few extracts that you find enjoyable.","zh":"只挑几段你自己喜欢的文本是不够的。","source":"original","number":50},{"en":"You need to consider the different kind of emotion that each extract should present, from sorrow through to ecstasy.","zh":"你需要考虑每篇节选应该呈现的各种情绪，从悲伤直到狂喜。","source":"original","number":51}]},{"id":"drama-v-49","term":"sorrow","type":"word","sourceOrder":49,"zh":"悲伤","pos":"n.","ipa":"ˈsɒrəʊ","stars":3,"note":"悲痛、忧伤；与 ecstasy 构成范围两端","paragraph":"听力原文","examples":[{"en":"You need to consider the different kind of emotion that each extract should present, from sorrow through to ecstasy.","zh":"你需要考虑每篇节选应该呈现的各种情绪，从悲伤直到狂喜。","source":"original","number":51}]},{"id":"drama-v-50","term":"ecstasy","type":"word","sourceOrder":50,"zh":"狂喜","pos":"n.","ipa":"ˈekstəsi","stars":5,"note":"极大的喜悦；注意语境而非其他含义","paragraph":"听力原文","memory":{"parts":"ecstasy → ecstatic（词族）","tip":"把 ecstasy 与 sorrow 放在情绪光谱两端，帮助记“狂喜”；不按外形硬拆。","family":"ecstasy, ecstatic"},"examples":[{"en":"You need to consider the different kind of emotion that each extract should present, from sorrow through to ecstasy.","zh":"你需要考虑每篇节选应该呈现的各种情绪，从悲伤直到狂喜。","source":"original","number":51}]},{"id":"drama-v-51","term":"classical","type":"word","sourceOrder":51,"zh":"古典的","pos":"adj.","ipa":"ˈklæsɪkəl","stars":3,"note":"经典文学／古典音乐的；classical vs contemporary","paragraph":"听力原文","examples":[{"en":"Classical stuff is all well and good, but include many more contemporary sources.","zh":"经典素材固然不错，但还应加入更多当代作品。","source":"original","number":52}]},{"id":"drama-v-52","term":"contemporary","type":"word","sourceOrder":52,"zh":"当代的","pos":"adj.","ipa":"kənˈtempərəri","stars":4,"note":"同一时代的；Q26 非“增加经典”，而是现代素材","paragraph":"听力原文","memory":{"parts":"tempor-（时间）与 contemporary 联想","tip":"“同一时间”的意象帮助记同一时代的、当代的；本文要求更多 contemporary sources。","family":"contemporary, temporary, temporal"},"examples":[{"en":"Classical stuff is all well and good, but include many more contemporary sources.","zh":"经典素材固然不错，但还应加入更多当代作品。","source":"original","number":52}]},{"id":"drama-v-53","term":"flag","type":"word","sourceOrder":53,"zh":"标示、提出（问题）","pos":"v.","ipa":"flæɡ","stars":3,"note":"衰退（v.）；旗帜（n.）；flag up = 明确指出","paragraph":"听力原文","examples":[{"en":"Now, out of the twenty books you list, some are more useful than others, and I think you should flag up the disadvantages so that people don't waste money buying them.","zh":"你列出的20本书有些比其他的更实用；我认为应指出它们的缺点，避免大家花冤枉钱。","source":"original","number":56}]},{"id":"drama-v-54","term":"disadvantage","type":"word","sourceOrder":54,"zh":"缺点","pos":"n.","ipa":"ˌdɪsədˈvɑːntɪdʒ","stars":3,"note":"劣势；Q27–30 的统一任务","paragraph":"听力原文","examples":[{"en":"Now, out of the twenty books you list, some are more useful than others, and I think you should flag up the disadvantages so that people don't waste money buying them.","zh":"你列出的20本书有些比其他的更实用；我认为应指出它们的缺点，避免大家花冤枉钱。","source":"original","number":56}]},{"id":"drama-v-55","term":"historical","type":"word","sourceOrder":55,"zh":"历史的","pos":"adj.","ipa":"hɪˈstɒrɪkəl","stars":4,"note":"与历史有关的；与 historic（有历史意义的）区分","paragraph":"听力原文","memory":{"parts":"history（历史）→ historical","tip":"history 词族联想；historical 是与历史相关的，historic 强调有历史意义。","family":"history, historical, historic"},"examples":[{"en":"I know I recommended it for you to read for its historical perspective, but bear in mind it was written thirty years ago, and it shows.","zh":"我知道我曾推荐它的历史视角，但要记住它写于30年前，而且明显显得过时了。","source":"original","number":58}]},{"id":"drama-v-56","term":"perspective","type":"word","sourceOrder":56,"zh":"视角","pos":"n.","ipa":"pəˈspektɪv","stars":4,"note":"观点；透视；historical perspective","paragraph":"听力原文","memory":{"parts":"spect-（看）的词根联想","tip":"从“看事物的角度”记视角；historical perspective 是历史视角。","family":"perspective, inspect, spectator"},"examples":[{"en":"I know I recommended it for you to read for its historical perspective, but bear in mind it was written thirty years ago, and it shows.","zh":"我知道我曾推荐它的历史视角，但要记住它写于30年前，而且明显显得过时了。","source":"original","number":58}]},{"id":"drama-v-57","term":"narrow","type":"word","sourceOrder":57,"zh":"狭窄的、有限的","pos":"adj.","ipa":"ˈnærəʊ","stars":2,"note":"使变窄（v.）；narrow outlook = limited scope","paragraph":"听力原文","examples":[{"en":"I thought Improve Your Accent was interesting, but it's very narrow in its outlook, don't you think?","zh":"我觉得《Improve Your Accent》挺有趣，但它的视野很狭窄，你不觉得吗？","source":"original","number":60}]},{"id":"drama-v-58","term":"outlook","type":"word","sourceOrder":58,"zh":"视野、观点","pos":"n.","ipa":"ˈaʊtlʊk","stars":3,"note":"前景、展望；熟词生义：不是单纯“向外看”","paragraph":"听力原文","examples":[{"en":"I thought Improve Your Accent was interesting, but it's very narrow in its outlook, don't you think?","zh":"我觉得《Improve Your Accent》挺有趣，但它的视野很狭窄，你不觉得吗？","source":"original","number":60}]},{"id":"drama-v-59","term":"publisher","type":"word","sourceOrder":59,"zh":"出版商","pos":"n.","ipa":"ˈpʌblɪʃə","stars":3,"note":"出版机构；注意 books 状态来源","paragraph":"听力原文","examples":[{"en":"It's an expensive book, very useful, but according to the publishers, they're going to reissue it with new color photos, and at the moment it's out of print.","zh":"这本书很贵，也确实很实用，但据出版商说将重印新版配彩照；目前已无在售印本。","source":"original","number":63}]},{"id":"drama-v-60","term":"reissue","type":"word","sourceOrder":60,"zh":"再版、重新发行","pos":"v.","ipa":"ˌriːˈɪʃuː","stars":4,"note":"重新签发；书尚未再版 ≠ 现在可以买到","paragraph":"听力原文","memory":{"parts":"re-（再次）＋ issue（发行）","tip":"再次发行即再版；将来会 reissue 不等于现在已经有书可买。","family":"issue, reissue"},"examples":[{"en":"It's an expensive book, very useful, but according to the publishers, they're going to reissue it with new color photos, and at the moment it's out of print.","zh":"这本书很贵，也确实很实用，但据出版商说将重印新版配彩照；目前已无在售印本。","source":"original","number":63}]},{"id":"drama-v-61","term":"secondhand","type":"word","sourceOrder":61,"zh":"二手的","pos":"adj.","ipa":"ˌsekəndˈhænd","stars":2,"note":"间接得来的；secondhand copies","paragraph":"听力原文","examples":[{"en":"There aren't any secondhand copies out there, so tell them not to waste time looking for it.","zh":"市面上也没有二手本，所以告诉大家别浪费时间找它。","source":"original","number":64}]},{"id":"drama-v-62","term":"exaggerate","type":"word","sourceOrder":62,"zh":"夸大","pos":"v.","ipa":"ɪɡˈzædʒəreɪt","stars":5,"note":"言过其实；夸大结论 often misleading","paragraph":"听力原文","memory":{"parts":"exaggerate → exaggeration（词族）","tip":"把夸大的 claims 与 misleading 联系记忆，名词 exaggeration 表夸张。","family":"exaggerate, exaggerated, exaggeration"},"examples":[{"en":"It exaggerates its claims on how to be successful to such an extent that I think it is positively misleading.","zh":"这本书把“怎样成功”的说法夸大到一种程度，我认为简直是明显的误导。","source":"original","number":68}]},{"id":"drama-v-63","term":"claim","type":"word","sourceOrder":63,"zh":"声称、主张","pos":"n.","ipa":"kleɪm","stars":2,"note":"索赔；认领；主张权利；claims 在这里非保险索赔","paragraph":"听力原文","examples":[{"en":"It exaggerates its claims on how to be successful to such an extent that I think it is positively misleading.","zh":"这本书把“怎样成功”的说法夸大到一种程度，我认为简直是明显的误导。","source":"original","number":68}]},{"id":"drama-v-64","term":"extent","type":"word","sourceOrder":64,"zh":"程度","pos":"n.","ipa":"ɪkˈstent","stars":3,"note":"范围；to such an extent that...","paragraph":"听力原文","examples":[{"en":"It exaggerates its claims on how to be successful to such an extent that I think it is positively misleading.","zh":"这本书把“怎样成功”的说法夸大到一种程度，我认为简直是明显的误导。","source":"original","number":68}]},{"id":"drama-v-65","term":"positively","type":"word","sourceOrder":65,"zh":"确实、明显地（加强语气）","pos":"adv.","ipa":"ˈpɒzətɪvli","stars":4,"note":"积极地；熟词生义：positively misleading ≠ 积极误导","paragraph":"听力原文","memory":{"parts":"positive（明确的／积极的）＋ -ly","tip":"本文 positively 加强语气，意为确实、明显；positively misleading 不是正面赞扬。","family":"positive, positively"},"examples":[{"en":"It exaggerates its claims on how to be successful to such an extent that I think it is positively misleading.","zh":"这本书把“怎样成功”的说法夸大到一种程度，我认为简直是明显的误导。","source":"original","number":68}]},{"id":"drama-v-66","term":"misleading","type":"word","sourceOrder":66,"zh":"具有误导性的","pos":"adj.","ipa":"ˌmɪsˈliːdɪŋ","stars":4,"note":"引起错误印象的；Q30 主要批评","paragraph":"听力原文","memory":{"parts":"mis-（错误地）＋ lead（引导）＋ -ing","tip":"“引向错误”即误导；lead 在这个词中读 /liːd/。","family":"mislead, misleading, misled"},"examples":[{"en":"It exaggerates its claims on how to be successful to such an extent that I think it is positively misleading.","zh":"这本书把“怎样成功”的说法夸大到一种程度，我认为简直是明显的误导。","source":"original","number":68}]},{"id":"drama-v-67","term":"biased","type":"word","sourceOrder":67,"zh":"有偏见的","pos":"adj.","ipa":"ˈbaɪəst","stars":4,"note":"倾向一方的；maybe I'm biased 不否认先前批评","paragraph":"听力原文","memory":{"parts":"bias（偏见）＋ -ed","tip":"用 balanced（平衡的）与 biased（偏颇的）对照记；自称有偏见不撤销前句批评。","family":"bias, biased, unbiased"},"examples":[{"en":"But maybe I'm biased.","zh":"不过，也许我有偏见。","source":"original","number":69}]},{"id":"drama-v-68","term":"reliable","type":"word","sourceOrder":68,"zh":"可靠的（延伸）","pos":"adj.","ipa":"rɪˈlaɪəbəl","stars":3,"note":"可信的；与 misleading 反义联想","paragraph":"词汇与语块","examples":[{"en":"Choose reliable sources when planning a workshop.","zh":"设计工作坊时，请选择可靠的资料来源。","source":"supplemental"}]},{"id":"drama-v-69","term":"prioritise","type":"word","sourceOrder":69,"zh":"优先处理（策略词）","pos":"v.","ipa":"praɪˈɒrətaɪz","stars":4,"note":"排定优先级；考试中优先听提问焦点","paragraph":"词汇与语块","memory":{"parts":"priority（优先事项）→ prioritise（排优先级）","tip":"从 priority 记动词形式，英式 -ise 与美式 -ize 对应；这是策略拓展词。","family":"priority, prioritise, prioritisation"},"examples":[{"en":"Prioritise the main point after the contrast marker.","zh":"优先关注转折标记之后的主要观点。","source":"supplemental"}]},{"id":"drama-p-1","term":"be delighted that","type":"phrase","sourceOrder":70,"zh":"很高兴……","pos":"短语／语块","ipa":"biː dɪˈlaɪtɪd ðæt","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"Well, I'm delighted that you've joined the drama department.","zh":"我很高兴你加入了戏剧系。","source":"original","number":6},{"en":"I am delighted that you passed the audition.","zh":"你通过试镜，我很高兴。","source":"supplemental"},{"en":"She was delighted that the team agreed.","zh":"团队同意了，她很高兴。","source":"supplemental"},{"en":"We are delighted that you can join us.","zh":"你能加入我们，我们很高兴。","source":"supplemental"}]},{"id":"drama-p-2","term":"be clear about","type":"phrase","sourceOrder":71,"zh":"对……有清楚认识","pos":"短语／语块","ipa":"biː klɪə əˈbaʊt","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"So let's ensure that you're clear about what you'll be doing in the first voice coaching workshop you run next week.","zh":"因此，我们要确认你清楚下周首场声音指导工作坊要做些什么。","source":"original","number":8},{"en":"Be clear about your role before the rehearsal.","zh":"排练前要弄清自己的职责。","source":"supplemental"},{"en":"Are you clear about the deadline?","zh":"你清楚截止日期吗？","source":"supplemental"},{"en":"The students were clear about the objectives.","zh":"学生们明确了目标。","source":"supplemental"}]},{"id":"drama-p-3","term":"run a workshop","type":"phrase","sourceOrder":72,"zh":"组织／主持工作坊","pos":"短语／语块","ipa":"rʌn ə ˈwɜːkʃɒp","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"You will hear a discussion between Fiona, who is the head of a college drama department, and a new tutor called Ed, who is preparing to run a voice coaching workshop for drama students.","zh":"你将听到菲奥娜（学院戏剧系主任）与新导师埃德的讨论；埃德正在准备为戏剧专业学生开设声音指导工作坊。","source":"original","number":2},{"en":"She will run a workshop on public speaking.","zh":"她将开设一场公众演讲工作坊。","source":"supplemental"},{"en":"The college runs workshops every term.","zh":"学院每学期举办工作坊。","source":"supplemental"},{"en":"Who is running tomorrow’s workshop?","zh":"谁主持明天的工作坊？","source":"supplemental"}]},{"id":"drama-p-4","term":"project one’s voice","type":"phrase","sourceOrder":73,"zh":"让声音清楚地传到远处","pos":"短语／语块","ipa":"prəˈdʒekt wʌnz vɔɪs","stars":4,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"I'll be observing you working with the students as you show them how to project their voices on stage.","zh":"我会在你教学生如何在舞台上将声音清晰传出去时，观察你的教学表现。","source":"original","number":10},{"en":"Actors must project their voices on a large stage.","zh":"演员在大舞台上要把声音传远。","source":"supplemental"},{"en":"Try to project your voice without shouting.","zh":"试着不靠喊叫来传声。","source":"supplemental"},{"en":"He struggled to project his voice outdoors.","zh":"他在户外很难让声音传远。","source":"supplemental"}]},{"id":"drama-p-5","term":"cope with","type":"phrase","sourceOrder":74,"zh":"应对、处理","pos":"短语／语块","ipa":"kəʊp wɪð","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"I'll be evaluating how you cope with the practical activities as well as the theory.","zh":"我会评估你应对实践活动和理论教学的能力。","source":"original","number":11},{"en":"Can you cope with last-minute changes?","zh":"你能应付临时变更吗？","source":"supplemental"},{"en":"She coped with the pressure very well.","zh":"她很好地承受了压力。","source":"supplemental"},{"en":"The tutor helps students cope with nerves.","zh":"导师帮助学生克服紧张。","source":"supplemental"}]},{"id":"drama-p-6","term":"as well as","type":"phrase","sourceOrder":75,"zh":"以及；除……之外还","pos":"短语／语块","ipa":"æz wel æz","stars":2,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"I'll be evaluating how you cope with the practical activities as well as the theory.","zh":"我会评估你应对实践活动和理论教学的能力。","source":"original","number":11},{"en":"The course includes theory as well as practice.","zh":"课程包括理论和实践。","source":"supplemental"},{"en":"He teaches pronunciation as well as acting.","zh":"他既教发音也教表演。","source":"supplemental"},{"en":"We need confidence as well as skill.","zh":"我们既需要技能也需要自信。","source":"supplemental"}]},{"id":"drama-p-7","term":"if all goes well","type":"phrase","sourceOrder":76,"zh":"如果一切顺利","pos":"短语／语块","ipa":"ɪf ɔːl ɡəʊz wel","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"And if all goes well, you'll then have finished the final stage of your voice coach diploma.","zh":"如果一切顺利，你就完成声音指导师文凭的最后阶段了。","source":"original","number":12},{"en":"If all goes well, the show will open on Friday.","zh":"如果顺利，演出周五开幕。","source":"supplemental"},{"en":"We will finish early if all goes well.","zh":"一切顺利的话我们会提前结束。","source":"supplemental"},{"en":"If all goes well, she will receive her certificate.","zh":"顺利的话她会拿到证书。","source":"supplemental"}]},{"id":"drama-p-8","term":"think through","type":"phrase","sourceOrder":77,"zh":"仔细考虑（步骤／后果）","pos":"短语／语块","ipa":"θɪŋk θruː","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"Anyway, I've thought through the workshop, and I've done a plan to highlight the key areas I intend to cover.","zh":"总之，我已经把工作坊仔细想过，并拟定了一份计划，突出要讲的重点领域。","source":"original","number":14},{"en":"Think through the plan before you submit it.","zh":"提交前仔细考虑计划。","source":"supplemental"},{"en":"He thought through every stage of the lesson.","zh":"他仔细考虑了课程的每个阶段。","source":"supplemental"},{"en":"We need to think this decision through.","zh":"我们需要全面考虑这一决定。","source":"supplemental"}]},{"id":"drama-p-9","term":"begin with","type":"phrase","sourceOrder":78,"zh":"以……开始","pos":"短语／语块","ipa":"bɪˈɡɪn wɪð","stars":2,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"You say you want to begin with the students sitting in star-shaped patterns.","zh":"你说打算先让学生按照星形布局坐好。","source":"original","number":19},{"en":"Begin with a short warm-up.","zh":"先进行简短热身。","source":"supplemental"},{"en":"The lecture begins with an example.","zh":"讲座以一个例子开场。","source":"supplemental"},{"en":"We began with a discussion of goals.","zh":"我们先讨论目标。","source":"supplemental"}]},{"id":"drama-p-10","term":"in a circle","type":"phrase","sourceOrder":79,"zh":"围成一圈","pos":"短语／语块","ipa":"ɪn ə ˈsɜːkəl","stars":2,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"I like trainees sitting cross-legged in a circle.","zh":"我喜欢让学员们盘腿围坐成圈。","source":"original","number":22},{"en":"Please sit in a circle.","zh":"请围坐成一圈。","source":"supplemental"},{"en":"The children stood in a circle.","zh":"孩子们围成一个圈。","source":"supplemental"},{"en":"We arranged the chairs in a circle.","zh":"我们把椅子围成了一圈。","source":"supplemental"}]},{"id":"drama-p-11","term":"in rows","type":"phrase","sourceOrder":80,"zh":"排成行／列","pos":"短语／语块","ipa":"ɪn rəʊz","stars":2,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"Other people like students in rows.","zh":"另一些人喜欢学生排成行。","source":"original","number":23},{"en":"The seats were arranged in rows.","zh":"座位排成多行。","source":"supplemental"},{"en":"Students stood in rows near the door.","zh":"学生在门旁排成几列。","source":"supplemental"},{"en":"Plant the trees in neat rows.","zh":"把树栽成整齐的行。","source":"supplemental"}]},{"id":"drama-p-12","term":"it doesn’t matter which…","type":"phrase","sourceOrder":81,"zh":"哪一个都无所谓","pos":"短语／语块","ipa":"ɪt ˈdʌzənt ˈmætə wɪtʃ …","stars":4,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"But it doesn't matter which one I use at the beginning of a workshop.","zh":"不过，在工作坊开始时我采用哪种座位布局并不重要，对吗？","source":"original","number":26},{"en":"It doesn’t matter which room we use.","zh":"我们用哪个教室都可以。","source":"supplemental"},{"en":"It doesn’t matter which date you choose.","zh":"你选哪个日期都行。","source":"supplemental"},{"en":"It doesn’t matter which example comes first.","zh":"哪个例子先讲都没关系。","source":"supplemental"}]},{"id":"drama-p-13","term":"feel comfortable with","type":"phrase","sourceOrder":82,"zh":"感觉适合、用着顺手","pos":"短语／语块","ipa":"fiːl ˈkʌmftəbəl wɪð","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"It's whatever you feel comfortable with.","zh":"你觉得哪种用着顺手就选哪种。","source":"original","number":27},{"en":"Choose a method you feel comfortable with.","zh":"选一种你用着顺手的方法。","source":"supplemental"},{"en":"I don’t feel comfortable with that arrangement.","zh":"我不太认可那个安排。","source":"supplemental"},{"en":"She feels comfortable with group discussions.","zh":"她对小组讨论很自在。","source":"supplemental"}]},{"id":"drama-p-14","term":"in the initial phase","type":"phrase","sourceOrder":83,"zh":"在初始阶段","pos":"短语／语块","ipa":"ɪn ðə ɪˈnɪʃəl feɪz","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"So in the initial phase, I explain the objectives of the session.","zh":"因此在初始阶段，我会说明本次课程的目标。","source":"original","number":29},{"en":"In the initial phase, we set our goals.","zh":"最初阶段我们设定目标。","source":"supplemental"},{"en":"Costs are higher in the initial phase.","zh":"起步阶段成本较高。","source":"supplemental"},{"en":"The initial phase focuses on breathing.","zh":"初始阶段重点练习呼吸。","source":"supplemental"}]},{"id":"drama-p-15","term":"weave in and out","type":"phrase","sourceOrder":84,"zh":"来回穿梭、迂回移动","pos":"短语／语块","ipa":"wiːv ɪn ənd aʊt","stars":4,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"Then in the first activity, you say they should quickly rise, walk briskly around the room, weaving in and out to avoid each other.","zh":"随后，在第一项活动中，你计划让学生迅速起身，在房间里快步穿行，避开彼此。","source":"original","number":31},{"en":"Cyclists weaved in and out of traffic.","zh":"骑车人在车流中穿梭。","source":"supplemental"},{"en":"The actors weaved in and out of the chairs.","zh":"演员们在椅子间穿梭。","source":"supplemental"},{"en":"Children were weaving in and out of the crowd.","zh":"孩子们在人群中穿来穿去。","source":"supplemental"}]},{"id":"drama-p-16","term":"get in someone’s way","type":"phrase","sourceOrder":85,"zh":"挡某人的路、妨碍某人","pos":"短语／语块","ipa":"ɡet ɪn ˈsʌmwʌnz weɪ","stars":4,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"I think it's important that they don't get in each other's way and that they learn to move within a confined space, aware of other people, but primarily concentrating on their own thoughts.","zh":"我认为重要的是：不要互相挡路；要学会在有限的空间中移动，留意他人，但主要关注自己的想法。","source":"original","number":33},{"en":"Don’t get in the dancers’ way.","zh":"不要挡舞者的路。","source":"supplemental"},{"en":"The boxes got in our way.","zh":"箱子妨碍我们通行。","source":"supplemental"},{"en":"He moved aside so he wouldn’t get in her way.","zh":"他让到一边，免得妨碍她。","source":"supplemental"}]},{"id":"drama-p-17","term":"be aware of","type":"phrase","sourceOrder":86,"zh":"意识到、注意到","pos":"短语／语块","ipa":"biː əˈweə əv","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"I think it's important that they don't get in each other's way and that they learn to move within a confined space, aware of other people, but primarily concentrating on their own thoughts.","zh":"我认为重要的是：不要互相挡路；要学会在有限的空间中移动，留意他人，但主要关注自己的想法。","source":"original","number":33},{"en":"Be aware of people behind you.","zh":"留意你身后的人。","source":"supplemental"},{"en":"Students should be aware of their posture.","zh":"学生要注意自己的姿势。","source":"supplemental"},{"en":"She is aware of the risks.","zh":"她了解风险。","source":"supplemental"}]},{"id":"drama-p-18","term":"concentrate on","type":"phrase","sourceOrder":87,"zh":"专注于","pos":"短语／语块","ipa":"ˈkɒnsəntreɪt ɒn","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"I think it's important that they don't get in each other's way and that they learn to move within a confined space, aware of other people, but primarily concentrating on their own thoughts.","zh":"我认为重要的是：不要互相挡路；要学会在有限的空间中移动，留意他人，但主要关注自己的想法。","source":"original","number":33},{"en":"Concentrate on your breathing.","zh":"专注你的呼吸。","source":"supplemental"},{"en":"He concentrated on the speaker’s main point.","zh":"他专注听讲话者的核心观点。","source":"supplemental"},{"en":"Try to concentrate on one task.","zh":"尽量专注一项任务。","source":"supplemental"}]},{"id":"drama-p-19","term":"omit to mention","type":"phrase","sourceOrder":88,"zh":"遗漏提及","pos":"短语／语块","ipa":"əˈmɪt tə ˈmenʃən","stars":4,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"But in your plan, you've omitted to mention that in the second activity, you will get the students to pair off.","zh":"但你的计划漏写了：第二项活动要让学生两两配对。","source":"original","number":35},{"en":"The report omitted to mention the cost.","zh":"报告漏提了费用。","source":"supplemental"},{"en":"He omitted to mention the second activity.","zh":"他漏说了第二个活动。","source":"supplemental"},{"en":"Don’t omit to mention the deadline.","zh":"别忘了提截止日期。","source":"supplemental"}]},{"id":"drama-p-20","term":"pair off","type":"phrase","sourceOrder":89,"zh":"两两配对","pos":"短语／语块","ipa":"peə ɒf","stars":2,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"But in your plan, you've omitted to mention that in the second activity, you will get the students to pair off.","zh":"但你的计划漏写了：第二项活动要让学生两两配对。","source":"original","number":35},{"en":"The students paired off for practice.","zh":"学生两两配对练习。","source":"supplemental"},{"en":"Please pair off and discuss the question.","zh":"请两人一组讨论问题。","source":"supplemental"},{"en":"The dancers paired off quickly.","zh":"舞者迅速结成一对对。","source":"supplemental"}]},{"id":"drama-p-21","term":"listen to each other","type":"phrase","sourceOrder":90,"zh":"互相倾听","pos":"短语／语块","ipa":"ˈlɪsən tə iːtʃ ˈʌðə","stars":2,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"So you need to rethink that section and include reasons why it's essential for them to listen to each other talking.","zh":"因此，你需要重新考虑该部分，并解释为什么互相倾听说话非常必要。","source":"original","number":36},{"en":"Partners must listen to each other carefully.","zh":"搭档必须认真倾听对方。","source":"supplemental"},{"en":"Good teams listen to each other.","zh":"优秀团队会彼此倾听。","source":"supplemental"},{"en":"They learnt to listen to each other’s ideas.","zh":"他们学会倾听彼此的想法。","source":"supplemental"}]},{"id":"drama-p-22","term":"at the same time","type":"phrase","sourceOrder":91,"zh":"与此同时","pos":"短语／语块","ipa":"æt ðə seɪm taɪm","stars":2,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"And at the same time, get them to think about their posture because that governs their lung capacity and most crucially, their breathing.","zh":"同时让他们注意姿势，因为姿势会影响肺活量，更关键的是呼吸。","source":"original","number":38},{"en":"Speak clearly and relax at the same time.","zh":"说清楚话，同时保持放松。","source":"supplemental"},{"en":"She smiled and took notes at the same time.","zh":"她一边微笑一边记笔记。","source":"supplemental"},{"en":"We must consider cost and quality at the same time.","zh":"要同时考虑成本与质量。","source":"supplemental"}]},{"id":"drama-p-23","term":"bear in mind","type":"phrase","sourceOrder":92,"zh":"记住；考虑到","pos":"短语／语块","ipa":"beə ɪn maɪnd","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"So bearing in mind that voice projection is not shouting, later in the course, you'll need to work in a much bigger space.","zh":"因此要记住，声音投射不是喊叫；在课程后期，你需要到大得多的空间训练。","source":"original","number":43},{"en":"Bear in mind that the hall is very large.","zh":"要记住大厅很大。","source":"supplemental"},{"en":"Bear in mind the time limit.","zh":"记得考虑时间限制。","source":"supplemental"},{"en":"You should bear this warning in mind.","zh":"你应牢记这个提醒。","source":"supplemental"}]},{"id":"drama-p-24","term":"there’s no reason why…couldn’t","type":"phrase","sourceOrder":93,"zh":"没有理由不能……","pos":"短语／语块","ipa":"ðeəz nəʊ ˈriːzən waɪ … ˈkʊdənt","stars":4,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"Ideally, an enclosed space, but there's no reason why you couldn't go somewhere outdoors, although I'd avoid a very public space like a park.","zh":"理想情况是封闭空间，但也完全可以去户外；只是我会避免公园那样过于公共的场所。","source":"original","number":46},{"en":"There’s no reason why we couldn’t meet outside.","zh":"我们完全可以在室外见面。","source":"supplemental"},{"en":"There’s no reason why she couldn’t try again.","zh":"她完全可以再试一次。","source":"supplemental"},{"en":"There’s no reason why the plan couldn’t work.","zh":"这个方案没理由行不通。","source":"supplemental"}]},{"id":"drama-p-25","term":"leave something to be desired","type":"phrase","sourceOrder":94,"zh":"尚不理想；有待改进","pos":"短语／语块","ipa":"liːv ˈsʌmθɪŋ tə biː dɪˈzaɪəd","stars":4,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。 注意：leave a lot / something / a little to be desired 表示仍有不足；leave little / nothing to be desired 表示几乎无可挑剔。请按完整搭配理解，不能忽略 a。","paragraph":"听力原文","examples":[{"en":"Now, your next activity on how to convey emotion on stage is fine, but your selection of texts for the students to experience emotional depth leaves a little to be desired.","zh":"接下来你关于舞台情感表达的活动本身不错，但供学生体验情感深度的选文仍有改进空间。","source":"original","number":49},{"en":"The sound quality leaves a lot to be desired.","zh":"音质仍有很大提升空间。","source":"supplemental"},{"en":"His timing leaves something to be desired.","zh":"他的时间把握有待改善。","source":"supplemental"},{"en":"The final draft leaves little to be desired.","zh":"终稿几乎无可挑剔。","source":"supplemental"}]},{"id":"drama-p-26","term":"from A through to B","type":"phrase","sourceOrder":95,"zh":"从 A 一直到 B（覆盖连续范围）","pos":"短语／语块","ipa":"frəm eɪ θruː tə biː","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"You need to consider the different kind of emotion that each extract should present, from sorrow through to ecstasy.","zh":"你需要考虑每篇节选应该呈现的各种情绪，从悲伤直到狂喜。","source":"original","number":51},{"en":"The book covers ages from five through to ten.","zh":"书面向5到10岁的年龄段。","source":"supplemental"},{"en":"We practise emotions from fear through to joy.","zh":"我们练习从恐惧到喜悦的情绪。","source":"supplemental"},{"en":"The exhibition traces art from 1900 through to today.","zh":"展览追溯1900年至今的艺术。","source":"supplemental"}]},{"id":"drama-p-27","term":"all well and good","type":"phrase","sourceOrder":96,"zh":"固然不错（但常有转折）","pos":"短语／语块","ipa":"ɔːl wel ənd ɡʊd","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"Classical stuff is all well and good, but include many more contemporary sources.","zh":"经典素材固然不错，但还应加入更多当代作品。","source":"original","number":52},{"en":"Theory is all well and good, but we need practice.","zh":"理论固然好，但需要练习。","source":"supplemental"},{"en":"The design is all well and good, but it costs too much.","zh":"设计不错，但太贵。","source":"supplemental"},{"en":"Advice is all well and good, but action matters.","zh":"建议虽好，行动更重要。","source":"supplemental"}]},{"id":"drama-p-28","term":"flag up","type":"phrase","sourceOrder":97,"zh":"明确指出；提示注意","pos":"短语／语块","ipa":"flæɡ ʌp","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"Now, out of the twenty books you list, some are more useful than others, and I think you should flag up the disadvantages so that people don't waste money buying them.","zh":"你列出的20本书有些比其他的更实用；我认为应指出它们的缺点，避免大家花冤枉钱。","source":"original","number":56},{"en":"Flag up any problems in the report.","zh":"在报告中指出所有问题。","source":"supplemental"},{"en":"She flagged up the lack of examples.","zh":"她特别指出例子不足。","source":"supplemental"},{"en":"We should flag up the safety risks.","zh":"我们应明确提示安全风险。","source":"supplemental"}]},{"id":"drama-p-29","term":"bear in mind that","type":"phrase","sourceOrder":98,"zh":"记住……这一事实","pos":"短语／语块","ipa":"beə ɪn maɪnd ðæt","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"I know I recommended it for you to read for its historical perspective, but bear in mind it was written thirty years ago, and it shows.","zh":"我知道我曾推荐它的历史视角，但要记住它写于30年前，而且明显显得过时了。","source":"original","number":58},{"en":"Bear in mind that the book is thirty years old.","zh":"要记住这书已写成三十年。","source":"supplemental"},{"en":"Bear in mind that prices can change.","zh":"记住价格可能变化。","source":"supplemental"},{"en":"Bear in mind that not every answer is stated directly.","zh":"记住并非每个答案都直接出现。","source":"supplemental"}]},{"id":"drama-p-30","term":"narrow in one’s outlook","type":"phrase","sourceOrder":99,"zh":"视野狭窄／观点局限","pos":"短语／语块","ipa":"ˈnærəʊ ɪn wʌnz ˈaʊtlʊk","stars":4,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"I thought Improve Your Accent was interesting, but it's very narrow in its outlook, don't you think?","zh":"我觉得《Improve Your Accent》挺有趣，但它的视野很狭窄，你不觉得吗？","source":"original","number":60},{"en":"The article is narrow in its outlook.","zh":"这篇文章视角有限。","source":"supplemental"},{"en":"The policy seems narrow in its outlook.","zh":"这项政策似乎视野狭窄。","source":"supplemental"},{"en":"The book is useful but narrow in its outlook.","zh":"这本书有用但观点局限。","source":"supplemental"}]},{"id":"drama-p-31","term":"according to","type":"phrase","sourceOrder":100,"zh":"根据（某人／某资料）","pos":"短语／语块","ipa":"əˈkɔːdɪŋ tə","stars":2,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"It's an expensive book, very useful, but according to the publishers, they're going to reissue it with new color photos, and at the moment it's out of print.","zh":"这本书很贵，也确实很实用，但据出版商说将重印新版配彩照；目前已无在售印本。","source":"original","number":63},{"en":"According to the publisher, a new edition is planned.","zh":"据出版社说，将有新版。","source":"supplemental"},{"en":"According to the timetable, we finish at six.","zh":"根据时间表，我们六点结束。","source":"supplemental"},{"en":"According to Fiona, the text selection is limited.","zh":"据菲奥娜说，选文范围不足。","source":"supplemental"}]},{"id":"drama-p-32","term":"out of print","type":"phrase","sourceOrder":101,"zh":"已绝版／没有新书在印","pos":"短语／语块","ipa":"aʊt əv prɪnt","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"It's an expensive book, very useful, but according to the publishers, they're going to reissue it with new color photos, and at the moment it's out of print.","zh":"这本书很贵，也确实很实用，但据出版商说将重印新版配彩照；目前已无在售印本。","source":"original","number":63},{"en":"That dictionary is now out of print.","zh":"那本词典现已绝版。","source":"supplemental"},{"en":"The old edition went out of print years ago.","zh":"旧版多年前就停印了。","source":"supplemental"},{"en":"Ask the library if the book is out of print.","zh":"问问图书馆这本书是否停印。","source":"supplemental"}]},{"id":"drama-p-33","term":"not waste time doing","type":"phrase","sourceOrder":102,"zh":"不要浪费时间做……","pos":"短语／语块","ipa":"nɒt weɪst taɪm ˈduːɪŋ","stars":3,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"There aren't any secondhand copies out there, so tell them not to waste time looking for it.","zh":"市面上也没有二手本，所以告诉大家别浪费时间找它。","source":"original","number":64},{"en":"Don’t waste time looking for that edition.","zh":"别浪费时间找那个版本。","source":"supplemental"},{"en":"She refused to waste time arguing.","zh":"她不愿浪费时间争论。","source":"supplemental"},{"en":"We shouldn’t waste time on irrelevant details.","zh":"不该把时间浪费在无关细节上。","source":"supplemental"}]},{"id":"drama-p-34","term":"to such an extent that","type":"phrase","sourceOrder":103,"zh":"达到如此程度，以致……","pos":"短语／语块","ipa":"tə sʌtʃ ən ɪkˈstent ðæt","stars":4,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"It exaggerates its claims on how to be successful to such an extent that I think it is positively misleading.","zh":"这本书把“怎样成功”的说法夸大到一种程度，我认为简直是明显的误导。","source":"original","number":68},{"en":"The hall echoed to such an extent that we moved rooms.","zh":"大厅回声太大，以致我们换了房间。","source":"supplemental"},{"en":"He practised to such an extent that he lost his voice.","zh":"他练得太多，以致失声。","source":"supplemental"},{"en":"The claim was exaggerated to such an extent that it misled readers.","zh":"这说法夸大到误导读者的程度。","source":"supplemental"}]},{"id":"drama-p-35","term":"make a note of","type":"phrase","sourceOrder":104,"zh":"记下","pos":"短语／语块","ipa":"meɪk ə nəʊt əv","stars":2,"note":"保留讲义短语。语境听写采用原文实际词形；one’s、someone’s、A/B 或省略号在句中会被具体词语替换。","paragraph":"听力原文","examples":[{"en":"[laughs] Okay, I'll make a note of that.","zh":"（笑）好的，我会记下来。","source":"original","number":70},{"en":"Make a note of the correct spelling.","zh":"记下正确拼写。","source":"supplemental"},{"en":"I made a note of her feedback.","zh":"我记下她的反馈。","source":"supplemental"},{"en":"Please make a note of the page number.","zh":"请记录页码。","source":"supplemental"}]}],"sentences":[{"en":"Part three.","zh":"第三部分。","speaker":"考官","paragraph":"听力原文","note":"考官提示：Part 3 是双人学术讨论，关注双方观点的回应与修正。"},{"en":"You will hear a discussion between Fiona, who is the head of a college drama department, and a new tutor called Ed, who is preparing to run a voice coaching workshop for drama students.","zh":"你将听到菲奥娜（学院戏剧系主任）与新导师埃德的讨论；埃德正在准备为戏剧专业学生开设声音指导工作坊。","speaker":"考官","paragraph":"听力原文","note":"句子主干 You will hear a discussion between A and B；两个 who 分别修饰 Fiona 和 Ed。run a workshop = 开办工作坊。"},{"en":"First, you have some time to look at questions twenty-one to twenty-six.","zh":"首先，你有时间查看第21—26题。","speaker":"考官","paragraph":"听力原文","note":"预读时间：先看题干问的是“目的、选择、活动、空间、文本”，而非逐字翻译。"},{"en":"Now listen carefully and answer questions twenty-one to twenty-six.","zh":"请认真听录音，回答第21—26题。","speaker":"考官","paragraph":"听力原文","note":"题序通常跟随说话内容；听到活动转换词就切换下一题。"},{"en":"Right, Ed.","zh":"好，埃德。","paragraph":"听力原文","note":"right 为话语标记，用于开始或转换话题。"},{"en":"Well, I'm delighted that you've joined the drama department.","zh":"我很高兴你加入了戏剧系。","paragraph":"听力原文","note":"be delighted that + 从句；you've joined 为现在完成时，强调已加入。"},{"en":"Now, part of my job is to support you during your probationary year.","zh":"我的部分职责是在你的试用年度支持你。","paragraph":"听力原文","note":"probationary year = 试用期；part of my job is to + 动词原形。"},{"en":"So let's ensure that you're clear about what you'll be doing in the first voice coaching workshop you run next week.","zh":"因此，我们要确认你清楚下周首场声音指导工作坊要做些什么。","paragraph":"听力原文","note":"ensure that…；be clear about + 宾语从句 what you'll be doing；you run next week 省略关系代词修饰 workshop。"},{"en":"Okay.","zh":"好的。","paragraph":"听力原文","note":"简短应答，表示接受安排。"},{"en":"I'll be observing you working with the students as you show them how to project their voices on stage.","zh":"我会在你教学生如何在舞台上将声音清晰传出去时，观察你的教学表现。","paragraph":"听力原文","note":"observe sb doing sth；show sb how to do；project one's voice = 让声音传到远处，不是“投影”。Q21 背景。"},{"en":"I'll be evaluating how you cope with the practical activities as well as the theory.","zh":"我会评估你应对实践活动和理论教学的能力。","paragraph":"听力原文","note":"evaluate + 宾语从句；cope with = 应对；as well as = 以及，不是单纯“同样好”。"},{"en":"And if all goes well, you'll then have finished the final stage of your voice coach diploma.","zh":"如果一切顺利，你就完成声音指导师文凭的最后阶段了。","paragraph":"听力原文","note":"if 条件从句；will have finished 是将来完成时。Q21：diploma ↔ qualification，答案 B。"},{"en":"That'd be great, Fiona.","zh":"那太好了，菲奥娜。","paragraph":"听力原文","note":"That'd = That would；表示希望与认同，不是已获得资格。"},{"en":"Anyway, I've thought through the workshop, and I've done a plan to highlight the key areas I intend to cover.","zh":"总之，我已经把工作坊仔细想过，并拟定了一份计划，突出要讲的重点领域。","paragraph":"听力原文","note":"think through = 仔细考虑；highlight = 突出；cover = 涉及／讲授（熟词生义）。"},{"en":"Good.","zh":"很好。","paragraph":"听力原文","note":"简短肯定，表示进入计划审核阶段。"},{"en":"Let's look at your plan.","zh":"我们看看你的计划。","paragraph":"听力原文","note":"Let's + 动词原形，提出共同动作。"},{"en":"Okay, so let's see.","zh":"好，那么来看看。","paragraph":"听力原文","note":"let's see 话语填充，后续观点更重要。"},{"en":"I'm glad you've thought about seating patterns.","zh":"我很高兴你考虑了座位排列方式。","paragraph":"听力原文","note":"seating patterns = 座位布局；think about = 考虑。"},{"en":"You say you want to begin with the students sitting in star-shaped patterns.","zh":"你说打算先让学生按照星形布局坐好。","paragraph":"听力原文","note":"begin with + 名词 / V-ing；with + 宾语 + V-ing 表伴随状态。"},{"en":"That's fine.","zh":"这样可以。","paragraph":"听力原文","note":"肯定一个方案，不等于规定必须使用它。"},{"en":"There are various seating patterns you can use at this stage.","zh":"在这个阶段，你可以选择多种座位布局。","paragraph":"听力原文","note":"various = 多种；you can use at this stage 是修饰 seating patterns 的定语从句。"},{"en":"I like trainees sitting cross-legged in a circle.","zh":"我喜欢让学员们盘腿围坐成圈。","paragraph":"听力原文","note":"like sb doing sth；cross-legged = 盘腿的；in a circle = 围成一圈。"},{"en":"Other people like students in rows.","zh":"另一些人喜欢学生排成行。","paragraph":"听力原文","note":"in rows = 成排；这是举例，不是唯一正确安排。"},{"en":"But actually, all these can be represented diagrammatically, which would be clearer than going into lots of detailed explanations like you've done here.","zh":"但实际上，这些布局都能用示意图呈现，这比你这里写大量细节解释更清晰。","paragraph":"听力原文","note":"can be represented 为被动；which 指代前面的图示表达方式；clearer than 比较级。Q22 易混：图示是“呈现计划”的建议，不是选哪种座位布局。"},{"en":"Oh, okay.","zh":"哦，明白了。","paragraph":"听力原文","note":"接受建议。"},{"en":"But it doesn't matter which one I use at the beginning of a workshop.","zh":"不过，在工作坊开始时我采用哪种座位布局并不重要，对吗？","paragraph":"听力原文","note":"it doesn't matter + 间接疑问从句；which one 指前述不同布局。Q22 真正提问焦点。"},{"en":"It's whatever you feel comfortable with.","zh":"你觉得哪种用着顺手就选哪种。","paragraph":"听力原文","note":"whatever 引导表语从句；feel comfortable with = 感觉合适。Q22 正解 C：具体布局不重要。"},{"en":"Fine.","zh":"好。","paragraph":"听力原文","note":"话题转入活动设计。"},{"en":"So in the initial phase, I explain the objectives of the session.","zh":"因此在初始阶段，我会说明本次课程的目标。","paragraph":"听力原文","note":"initial phase = 初始阶段；objectives = 目标（复数）。"},{"en":"Okay.","zh":"好的。","paragraph":"听力原文","note":"承接下文第一项活动。"},{"en":"Then in the first activity, you say they should quickly rise, walk briskly around the room, weaving in and out to avoid each other.","zh":"随后，在第一项活动中，你计划让学生迅速起身，在房间里快步穿行，避开彼此。","paragraph":"听力原文","note":"rise, walk 是并列动词；weaving 为伴随动作；to avoid 表目的。Q23 的场景铺垫。"},{"en":"Yes.","zh":"是。","paragraph":"听力原文","note":"确认第一项活动。"},{"en":"I think it's important that they don't get in each other's way and that they learn to move within a confined space, aware of other people, but primarily concentrating on their own thoughts.","zh":"我认为重要的是：不要互相挡路；要学会在有限的空间中移动，留意他人，但主要关注自己的想法。","paragraph":"听力原文","note":"两个 that 从句并列；aware of others 是让步背景；but primarily concentrating on their own thoughts 是重点。Q23 C；B 是“他人”信息诱饵。"},{"en":"Absolutely.","zh":"完全同意。","paragraph":"听力原文","note":"Fiona 明确赞同 Ed 对第一活动的理解。"},{"en":"But in your plan, you've omitted to mention that in the second activity, you will get the students to pair off.","zh":"但你的计划漏写了：第二项活动要让学生两两配对。","paragraph":"听力原文","note":"omit to do = 忘记／未做；get sb to do = 让某人做；pair off = 两两配对。Q24 干扰：配对不代表由导师指定具体搭档。"},{"en":"So you need to rethink that section and include reasons why it's essential for them to listen to each other talking.","zh":"因此，你需要重新考虑该部分，并解释为什么互相倾听说话非常必要。","paragraph":"听力原文","note":"rethink = 重新考虑；it's essential for sb to do；listen to sb doing。不是“准备演讲”。"},{"en":"It doesn't matter what they actually say.","zh":"他们具体说什么并不重要。","paragraph":"听力原文","note":"what 引导主语从句；排除 Q24 的 prepared speech（准备演讲）。"},{"en":"And at the same time, get them to think about their posture because that governs their lung capacity and most crucially, their breathing.","zh":"同时让他们注意姿势，因为姿势会影响肺活量，更关键的是呼吸。","paragraph":"听力原文","note":"because 表原因；that = their posture；govern = 决定／影响（熟词生义）。Q24：breathing ↔ breath control，答案 C。"},{"en":"Right.","zh":"好的。","paragraph":"听力原文","note":"表示听到并理解。"},{"en":"Will do.","zh":"我会照做。","paragraph":"听力原文","note":"省略主语 I；口语中表示接受任务。"},{"en":"Okay.","zh":"好的。","paragraph":"听力原文","note":"开始讨论训练场地。"},{"en":"Of course, a common issue in the UK is that we rehearse in small rooms, then transfer to a larger stage.","zh":"当然，英国常见的一个问题是：先在小房间排练，再转到更大的舞台。","paragraph":"听力原文","note":"表语从句 that…；rehearse = 排练；transfer to = 转移至。"},{"en":"So bearing in mind that voice projection is not shouting, later in the course, you'll need to work in a much bigger space.","zh":"因此要记住，声音投射不是喊叫；在课程后期，你需要到大得多的空间训练。","paragraph":"听力原文","note":"bearing in mind that… = 记住……；voice projection ≠ shouting。Q25 C 直接被否定。"},{"en":"Does it have to be an enclosed space?","zh":"一定要是封闭的室内空间吗？","paragraph":"听力原文","note":"have to = 必须；enclosed space = 封闭空间。"},{"en":"I suppose it does because ultimately they're going to work in a theater.","zh":"我想应该是，因为最终他们会在剧院工作。","paragraph":"听力原文","note":"I suppose 表个人推测；Ed 的推测不是 Fiona 的最终建议。"},{"en":"Ideally, an enclosed space, but there's no reason why you couldn't go somewhere outdoors, although I'd avoid a very public space like a park.","zh":"理想情况是封闭空间，但也完全可以去户外；只是我会避免公园那样过于公共的场所。","paragraph":"听力原文","note":"ideally 是偏好，but 转折放宽范围；there's no reason why you couldn't… = 没理由不能……；although 引入限制。Q25 A；park 明确需避免。"},{"en":"Right.","zh":"明白。","paragraph":"听力原文","note":"确认空间要求。"},{"en":"Thanks.","zh":"谢谢。","paragraph":"听力原文","note":"结束该建议。"},{"en":"Now, your next activity on how to convey emotion on stage is fine, but your selection of texts for the students to experience emotional depth leaves a little to be desired.","zh":"接下来你关于舞台情感表达的活动本身不错，但供学生体验情感深度的选文仍有改进空间。","paragraph":"听力原文","note":"convey = 传达；selection = 选择；leave a little to be desired = 不够理想（委婉批评）。Q26 重点在 but 后。"},{"en":"It's not enough to include a few extracts that you find enjoyable.","zh":"只挑几段你自己喜欢的文本是不够的。","paragraph":"听力原文","note":"it's not enough to do；that you find enjoyable 为定语从句。"},{"en":"You need to consider the different kind of emotion that each extract should present, from sorrow through to ecstasy.","zh":"你需要考虑每篇节选应该呈现的各种情绪，从悲伤直到狂喜。","paragraph":"听力原文","note":"from A through to B = 从A一直到B；情感跨度大。Q26 wider range。"},{"en":"Classical stuff is all well and good, but include many more contemporary sources.","zh":"经典素材固然不错，但还应加入更多当代作品。","paragraph":"听力原文","note":"all well and good = 固然不错；but 转折；contemporary = 当代的。Q26 A 是方向相反的干扰。"},{"en":"I understand.","zh":"我明白了。","paragraph":"听力原文","note":"Ed 接受修订建议。"},{"en":"Before you hear the rest of the discussion, you have some time to look at questions twenty-seven to thirty.","zh":"在听接下来的讨论前，你有时间查看第27—30题。","speaker":"考官","paragraph":"听力原文","note":"第二组预读：配对题应先看四本书的书名，再迅速扫描 A–G 特征选项。"},{"en":"Now listen and answer questions twenty-seven to thirty.","zh":"现在请听录音，回答第27—30题。","speaker":"考官","paragraph":"听力原文","note":"书名出现通常标示新题开始；警惕多个评价交织。"},{"en":"Now, out of the twenty books you list, some are more useful than others, and I think you should flag up the disadvantages so that people don't waste money buying them.","zh":"你列出的20本书有些比其他的更实用；我认为应指出它们的缺点，避免大家花冤枉钱。","paragraph":"听力原文","note":"out of… = 在……之中；flag up = 明确指出；so that 表目的。27—30 全是书籍缺点。"},{"en":"Take Vocal Instruction.","zh":"拿《Vocal Instruction》来说。","paragraph":"听力原文","note":"take X 用于“举……为例”；书名是定位锚点。"},{"en":"I know I recommended it for you to read for its historical perspective, but bear in mind it was written thirty years ago, and it shows.","zh":"我知道我曾推荐它的历史视角，但要记住它写于30年前，而且明显显得过时了。","paragraph":"听力原文","note":"but 后是当前缺点；it shows = 看得出来（书显旧）；Q27 E 对应年代久、内容过时。"},{"en":"Yeah, agreed.","zh":"是的，同意。","paragraph":"听力原文","note":"Ed 认同其缺点。"},{"en":"I thought Improve Your Accent was interesting, but it's very narrow in its outlook, don't you think?","zh":"我觉得《Improve Your Accent》挺有趣，但它的视野很狭窄，你不觉得吗？","paragraph":"听力原文","note":"narrow in its outlook = 视角有限；but 后评缺点。Q28 B。"},{"en":"Well, I'm not sure it's interesting.","zh":"嗯，我不确定它是否有趣。","paragraph":"听力原文","note":"Fiona 质疑“interesting”但未否认 narrow；不能把不同评价混为一谈。"},{"en":"And another one you need to warn people about is The Actor's Handbook.","zh":"你还应该提醒大家注意另一本——《The Actor's Handbook》。","paragraph":"听力原文","note":"warn sb about sth = 提醒某人注意；书名定位 Q29。"},{"en":"It's an expensive book, very useful, but according to the publishers, they're going to reissue it with new color photos, and at the moment it's out of print.","zh":"这本书很贵，也确实很实用，但据出版商说将重印新版配彩照；目前已无在售印本。","paragraph":"听力原文","note":"expensive、useful 是干扰；but 和 at the moment 锁定现状；out of print = 绝版／暂不再印。Q29 G 对应现时买不到。"},{"en":"There aren't any secondhand copies out there, so tell them not to waste time looking for it.","zh":"市面上也没有二手本，所以告诉大家别浪费时间找它。","paragraph":"听力原文","note":"there aren't any…；out there = 市面上；补强“unavailable”，不是单纯“太贵”。"},{"en":"Oh, right.","zh":"哦，原来如此。","paragraph":"听力原文","note":"得知新信息。"},{"en":"I didn't know that.","zh":"这我之前不知道。","paragraph":"听力原文","note":"didn't know 强调新发现，不是主要选项内容。"},{"en":"There's one more that I want to mention, and that's Confident Voice Delivery.","zh":"还有一本我想提，就是《Confident Voice Delivery》。","paragraph":"听力原文","note":"there's one more…；书名对应 Q30。"},{"en":"It exaggerates its claims on how to be successful to such an extent that I think it is positively misleading.","zh":"这本书把“怎样成功”的说法夸大到一种程度，我认为简直是明显的误导。","paragraph":"听力原文","note":"exaggerate = 夸大；to such an extent that… = 到如此程度以至于；positively = 确实／明显（非“积极地”）。Q30 D（按所给答案描述对应不切实际／夸大）。"},{"en":"But maybe I'm biased.","zh":"不过，也许我有偏见。","paragraph":"听力原文","note":"biased = 有偏见；自我保留并不推翻她已表达的批评。"},{"en":"[laughs] Okay, I'll make a note of that.","zh":"（笑）好的，我会记下来。","paragraph":"听力原文","note":"make a note of = 记下，确认接受建议。"},{"en":"Thanks.","zh":"谢谢。","paragraph":"听力原文","note":"常规道谢。"},{"en":"So the others...","zh":"那么其他几本……","paragraph":"听力原文","note":"未说完的过渡句，答案在前文已结束。"},{"en":"That is the end of part three.","zh":"第三部分结束。","speaker":"考官","paragraph":"听力原文","note":"考试结束提示。"},{"en":"You now have thirty seconds to check your answers to part three.","zh":"你有30秒检查第三部分的答案。","speaker":"考官","paragraph":"听力原文","note":"重点检查有没有漏答，以及配对字母是否抄错。"}],"questions":[{"number":22,"question":"The seating pattern that Ed chooses …","answer":"C","chosen":"B","focus":"which one 指使用哪种 seating pattern；Fiona 回答按自己舒适的来即可。","mistake":"推测：A visually illustrated：建议把计划画成图，针对“如何展示方案”，并非“选择何种座位”。B detailed：恰恰建议别写太多解释。","method":"看题干限定 that Ed chooses；不要把 plan presentation 错认成 seating choice。","evidence":[{"en":"But it doesn't matter which one I use at the beginning of a workshop.","zh":"不过，在工作坊开始时我采用哪种座位布局并不重要，对吗？","paragraph":"听力原文","note":"it doesn't matter + 间接疑问从句；which one 指前述不同布局。Q22 真正提问焦点。","highlight":""},{"en":"It's whatever you feel comfortable with.","zh":"你觉得哪种用着顺手就选哪种。","paragraph":"听力原文","note":"whatever 引导表语从句；feel comfortable with = 感觉合适。Q22 正解 C：具体布局不重要。","highlight":"whatever you feel comfortable with"}],"wrong":true,"type":"单项选择","instruction":"","choices":["A should be visually illustrated","B should be detailed","C is not particularly important"],"questionNote":"题干和部分选项按旧讲义还原。"},{"number":23,"question":"In the first activity, the students …","answer":"C","chosen":"B","focus":"primarily = 主要地；focus on themselves ↔ concentrating on their own thoughts。","mistake":"推测：B group contact：确实要避开别人、意识到他人，但 but primarily 后才是主要目标。A uncomfortable 未提。","method":"训练识别 primarily、mainly、above all：它们指示优先级。","evidence":[{"en":"I think it's important that they don't get in each other's way and that they learn to move within a confined space, aware of other people, but primarily concentrating on their own thoughts.","zh":"我认为重要的是：不要互相挡路；要学会在有限的空间中移动，留意他人，但主要关注自己的想法。","paragraph":"听力原文","note":"两个 that 从句并列；aware of others 是让步背景；but primarily concentrating on their own thoughts 是重点。Q23 C；B 是“他人”信息诱饵。","highlight":"primarily concentrating on their own thoughts"}],"wrong":true,"type":"单项选择","instruction":"","choices":["B should make contact with the group","C must focus on themselves"],"questionNote":"题干和部分选项按旧讲义还原。"},{"number":25,"question":"What does Fiona say about the larger space?","answer":"A","chosen":"B","focus":"enclosed = 室内封闭空间；outdoors = 户外；两者均可。","mistake":"推测：B park：被明确 avoid 否定；C shout：voice projection is not shouting 直接否定。","method":"把 ideally 与 must 区分；同时监测 although 后面的排除限制。","evidence":[{"en":"Ideally, an enclosed space, but there's no reason why you couldn't go somewhere outdoors, although I'd avoid a very public space like a park.","zh":"理想情况是封闭空间，但也完全可以去户外；只是我会避免公园那样过于公共的场所。","paragraph":"听力原文","note":"ideally 是偏好，but 转折放宽范围；there's no reason why you couldn't… = 没理由不能……；although 引入限制。Q25 A；park 明确需避免。","highlight":"somewhere outdoors"},{"en":"So bearing in mind that voice projection is not shouting, later in the course, you'll need to work in a much bigger space.","zh":"因此要记住，声音投射不是喊叫；在课程后期，你需要到大得多的空间训练。","paragraph":"听力原文","note":"bearing in mind that… = 记住……；voice projection ≠ shouting。Q25 C 直接被否定。","highlight":""}],"wrong":true,"type":"单项选择","instruction":"","choices":["A It could be outside or inside","B A park would be suitable"],"questionNote":"题干和部分选项按旧讲义还原。"}],"examples":[]};
